#!/usr/bin/env python3
# -*- coding: utf-8 -*-
#
# enodia-diag.py - ОДИН файл: подключиться к роутеру и снять РАСШИРЕННЫЙ роутерный
# диагностический дамп в файл. Коллектор (dump.sh) ВШИТ ниже как base64 - рядом НЕ нужен
# dump.sh. Нужен только enodia.py в той же папке (из него берём подключение: Router,
# DPAPI/keyring-пароль, IP роутера из settings.json, легаси-host-key-фикс для старого dropbear).
# Ничего на роутере НЕ меняет - только чтение состояния + безобидные пробы (curl/ping/ps/ip).
#
# Запуск (из папки, где лежит enodia.py):
#     py enodia-diag.py
# Результат: diag/enodia-diag-<дата>.txt  (секреты замаскированы dump.sh)
#
# ВАЖНО тестеру: снимать ЖЕЛАТЕЛЬНО в момент, когда рунет НЕ работает - тогда в дампе видно,
# что именно отвалилось (прямой egress / DNS / несущая), а не здоровый снимок.
#
# Коллектор = dump.sh (единый источник; он же за DiagDump в меню). При правках dump.sh
# пересобрать константу DUMP_B64: запустить dev/build-router-diag.py (перегенерит этот файл).

import os
import sys
import base64
import datetime

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
try:
    import enodia as b  # __main__-гард в enodia.py не даёт запуститься меню при импорте
except Exception as e:
    print("Рядом должен лежать enodia.py (из папки беты). Ошибка импорта:", e)
    sys.exit(2)

