def _router_host():
    try:
        h = b.load_router_host()
        if h:
            return h
    except Exception:
        pass
    return getattr(b, "DEFAULT_ROUTER_IP", None) or "192.168.31.1"


def main():
    host = _router_host()
    print("Роутер: %s  (пароль - из хранилища Enodia; PuTTY не нужен)" % host)

    router = b.Router(host, password_provider=b.get_stored_password)
    print("Снимаю состояние роутера (~10-25 c: пробы egress / socks / DNS)...")
    # DUMP_B64 = base64(скрипт) -> stdin -> роутер декодирует и исполняет, вывод -> base64.
    res = router.run(
        "printf '%s\\n'; base64 -d | sh | base64; printf '%s\\n'" % (BEGIN, END),
        stdin_data=DUMP_B64, silent=True,
    )
    out = getattr(res, "out", "") or ""
    if not out:
        print("Пустой ответ от роутера (связь / SSH / пароль?).")
        print("Проверьте доступ: py enodia.py -> «Доступ» (IP роутера, пароль).")
        return 1

    import re
    mm = re.search(r'(?s)' + BEGIN + r'(.*?)' + END, out)
    b64out = re.sub(r'\s', '', mm.group(1)) if mm else re.sub(r'\s', '', out)
    try:
        data = base64.b64decode(b64out)
    except Exception:
        print("Не удалось декодировать ответ (ожидался base64) - связь оборвалась / старый busybox.")
        return 1

    diag_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "diag")
    os.makedirs(diag_dir, exist_ok=True)
    ts = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
    out_file = os.path.join(diag_dir, "enodia-diag-%s.txt" % ts)
    user = getattr(b, "ROUTER_USER", "root")
    header = (
        # МОДЕЛЬ В ШАПКЕ НЕ ПИШЕМ, и это не забывчивость: ПК её здесь не знает, а вшитая («BE7000»)
        # ВРАЛА на всех прочих роутерах — дамп, снятый с AX3600, приезжал подписанным чужим железом,
        # и тестер переставал верить остальным числам (тот же класс, что стережёт C32). Настоящую
        # модель печатает router-lib.sh НА РОУТЕРЕ — первой же секцией «ОБЗОР РОУТЕРА».
        "# Enodia - РОУТЕРНЫЙ диагностический дамп (расширенный: прямой путь / альт-несущая / DNS / v6)\n"
        "# собран: %s  ПК -> %s@%s\n"
        "# Ключи, endpoint и публичные IP замаскированы скриптом dump.sh (эвристически).\n"
        "# ВСЁ РАВНО просмотрите файл перед публикацией.\n\n"
    ) % (datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"), user, host)
    with open(out_file, "wb") as fh:
        fh.write(b"\xef\xbb\xbf")  # UTF-8 BOM
        fh.write(header.encode("utf-8"))
        fh.write(data)
    size_kb = round(os.path.getsize(out_file) / 1024, 1)
    print("Готово: %s  (%s КБ)" % (out_file, size_kb))
    print("Пришлите этот файл. Секреты замаскированы (всё равно просмотрите их глазами перед отправкой).")
    return 0


if __name__ == "__main__":
    sys.exit(main())
